/* Additive read-only historical intelligence. Embedded index survives absent R2.
 * HI_DATA and HI_CORE are generated by build-smart; no runtime writes occur. */
var HI_PREVIOUS_FETCH=worker_default.fetch;
var HI_PARTITIONS=new Map(),HI_PARTITION_PENDING=new Map();
async function hiDigest(bytes){const hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');}
async function hiDecodeJSON(bytes,compression,maximumBytes){
 let decoded=bytes;
 if(compression==='gzip'){
  const reader=new Response(bytes).body.pipeThrough(new DecompressionStream('gzip')).getReader(),chunks=[];let size=0;
  try{while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>maximumBytes){await reader.cancel();throw new Error('Immutable JSON exceeds its decoded size bound.');}chunks.push(part.value);}}
  finally{reader.releaseLock();}
  const buffer=new Uint8Array(size);let offset=0;for(const chunk of chunks){buffer.set(chunk,offset);offset+=chunk.byteLength;}decoded=buffer;
 }
 if(decoded.byteLength>maximumBytes)throw new Error('Immutable JSON exceeds its decoded size bound.');
 return JSON.parse(new TextDecoder().decode(decoded));
}
function hiArchiveValid(data){
 if(data.version!==HI_DATA.version||data.asOf!==HI_DATA.asOf||!Array.isArray(data.records)||data.records.length!==HI_DATA.records.length||!Array.isArray(data.sources)||!Array.isArray(data.events)||!Array.isArray(data.exposures))return false;
 const expected=new Map(HI_DATA.records.map(r=>[r.id,r])),records=new Map(data.records.map(r=>[r.id,r])),sources=new Map(data.sources.map(s=>[s.id,s])),events=new Map(data.events.map(e=>[e.id,e])),series=new Map((data.series||[]).map(s=>[s.id,s]));
 if(records.size!==data.records.length||sources.size!==data.sources.length||events.size!==data.events.length||data.series&&series.size!==data.series.length||data.sources.some(s=>typeof s.id!=='string'||!s.id))return false;
 for(const record of data.records){
  const prior=expected.get(record.id);if(!prior||['type','name','emirate'].some(k=>record[k]!==prior[k])||(record.communityId||null)!==(prior.communityId||null))return false;
  if(!Array.isArray(record.historySeries)&&!Array.isArray(record.historySeriesIds))return false;
  if(!record.historySeries){if(record.historySeriesIds.some(id=>!series.has(id)))return false;record.historySeries=record.historySeriesIds.map(id=>({...series.get(id),points:series.get(id).points||[]}));}
  const previous=new Map((prior.historySeries||[]).map(s=>[s.id,s]));
  if(previous.size!==record.historySeries.length||new Set(record.historySeries.map(s=>s.id)).size!==record.historySeries.length)return false;
  for(const descriptor of record.historySeries){const original=previous.get(descriptor.id);if(!original||['scope','identityVerified','sourceId'].some(k=>descriptor[k]!==original[k])||!descriptor.id||!sources.has(descriptor.sourceId)||!['subject','area_context','asking_benchmark','community_context','published_reference'].includes(descriptor.scope)||typeof descriptor.identityVerified!=='boolean')return false;}
 }
 for(const event of data.events)if(!event.id||!Array.isArray(event.sourceIds)||event.sourceIds.some(id=>!sources.has(id)))return false;
 for(const exposure of data.exposures)if(!records.has(exposure.recordId)||!events.has(exposure.eventId))return false;
 for(const rule of data.exposureRules||[])if(!events.has(rule.eventId)||(rule.sourceIds||[]).some(id=>!sources.has(id)))return false;
 return true;
}
async function hiSnapshot(env){
 if(typeof HI_GET_DATA==='function')await HI_GET_DATA();
 const spec=HI_DATA.manifest?.r2;
 if(!spec?.key)return HI_DATA;
 try{
  if(!/^research\/published\//.test(spec.key)||spec.key.includes('..')||!/^[a-f0-9]{64}$/.test(spec.sha256||''))return HI_DATA;
  const binding=env?.[spec.binding||'MARKET_R2'],object=await binding?.get(spec.key);if(!object)return HI_DATA;
  const bytes=await object.arrayBuffer();if(bytes.byteLength>8*1024*1024||await hiDigest(bytes)!==spec.sha256)return HI_DATA;
  const data=await hiDecodeJSON(bytes,spec.compression||(/\.gz$/.test(spec.key)?'gzip':null),32*1024*1024);
  if(!hiArchiveValid(data))return HI_DATA;
  return data;
 }catch{return HI_DATA;}
}
async function hiPartition(pointer,data,env){
 const p=pointer.partition;if(!p?.key||!p.sha256||!/^research\/published\//.test(p.key)||p.key.includes('..')||!/^[a-f0-9]{64}$/.test(p.sha256))return null;
 const cacheKey=p.key+':'+p.sha256;
 if(HI_PARTITIONS.has(cacheKey))return HI_PARTITIONS.get(cacheKey);
 if(!HI_PARTITION_PENDING.has(cacheKey))HI_PARTITION_PENDING.set(cacheKey,(async()=>{
  try{
   const binding=env?.[data.manifest?.partitionBinding||data.manifest?.r2binding||'MARKET_R2'],object=await binding?.get(p.key);if(!object)return null;
   const bytes=await object.arrayBuffer();if(bytes.byteLength>8*1024*1024||await hiDigest(bytes)!==p.sha256)return null;
   const partition=await hiDecodeJSON(bytes,p.compression,32*1024*1024);if(partition.version!==data.version||!Array.isArray(partition.series))return null;
   if(HI_PARTITIONS.size>=128)HI_PARTITIONS.delete(HI_PARTITIONS.keys().next().value);
   HI_PARTITIONS.set(cacheKey,partition);return partition;
  }catch{return null;}
 })().finally(()=>HI_PARTITION_PENDING.delete(cacheKey)));
 return HI_PARTITION_PENDING.get(cacheKey);
}
async function hiHydrateRecord(record,data,env){
 const histories=await Promise.all((record.historySeries||[]).map(async(pointer)=>{
  if(!pointer.partition)return {...pointer,availability:pointer.availability||(pointer.points?.length?'embedded_native_points':'source_unavailable')};
  const partition=await hiPartition(pointer,data,env),series=partition?.series.find(s=>s.id===pointer.id);
  if(!series||!Array.isArray(series.points)||(Number.isInteger(pointer.pointCount)&&series.points.length!==pointer.pointCount))return {...pointer,availability:pointer.points?.length?'partial_embedded_context':'partition_unavailable',partitionLoaded:false};
  if(series.scope!==pointer.scope||series.identityVerified!==pointer.identityVerified||series.sourceId!==pointer.sourceId)return {...pointer,availability:'partition_identity_conflict',partitionLoaded:false};
  return {...pointer,...series,partition:pointer.partition,availability:'verified_immutable_partition',partitionLoaded:true};
 }));
 return {...record,historySeries:histories};
}
async function hiJSON(request,data,status=200){
 const text=JSON.stringify(data),digest=await hiDigest(new TextEncoder().encode(text)),etag='"hi-'+(data.version||HI_DATA.version)+'-'+digest+'"';
 const headers={'content-type':'application/json; charset=utf-8','x-content-type-options':'nosniff','cache-control':status===200?'public, max-age=60, s-maxage=300':'no-store','x-espacios-historical':data.version||HI_DATA.version,'etag':etag};
 if(status===405)headers.allow='GET, HEAD';
 if(status===200&&(request.headers.get('if-none-match')||'').split(',').map(s=>s.trim().replace(/^W\//,'')).includes(etag))return new Response(null,{status:304,headers});
 return new Response(request.method==='HEAD'?null:text,{status,headers});
}
worker_default.fetch=async function(request,env,ctx){
 const u=new URL(request.url),path=u.pathname.replace(/\/+$/,'');
 if(!['/map/api/events','/map/api/record-history','/map/api/event-studies'].includes(path))return HI_PREVIOUS_FETCH.call(this,request,env,ctx);
 if(u.hostname==='psrhomes.ae'||u.hostname.endsWith('.psrhomes.ae'))return hiJSON(request,{version:HI_DATA.version,error:'Not found'},404);
 if(!['GET','HEAD'].includes(request.method))return hiJSON(request,{version:HI_DATA.version,error:'Read-only endpoint'},405);
 const data=await hiSnapshot(env),recordId=u.searchParams.get('recordId'),record=recordId?data.records.find(r=>r.id===recordId):null;
 if(recordId&&!record)return hiJSON(request,{version:data.version,error:'Unknown catalogue record; project/community identity is not inferred from names.'},404);
 try{
  if(path==='/map/api/events'){
   const exposures=record?HI_CORE.recordExposures(data,record):(data.exposures||[]),ids=record?new Set(exposures.map(x=>x.eventId)):null;
   let events=(data.events||[]).filter(e=>!ids||ids.has(e.id));
   if(u.searchParams.has('category'))events=events.filter(e=>e.category===u.searchParams.get('category'));
   const from=u.searchParams.get('from'),to=u.searchParams.get('to');
   const fromDate=from?HI_CORE.parseEvidenceDate(from).start:null,toDate=to?HI_CORE.parseEvidenceDate(to).end:null;
   if(fromDate&&toDate&&fromDate>toDate)throw new TypeError('Event filter starts after its end.');
   if(fromDate||toDate)events=events.filter(e=>{try{const d=HI_CORE.parseEvidenceDate(e.eventDate||e.effectiveFrom||e.date);return(!fromDate||d.end>=fromDate)&&(!toDate||d.start<=toDate);}catch{return false;}});
   const visible=new Set(events.map(e=>e.id));
   return hiJSON(request,{version:data.version,asOf:data.asOf,recordId:recordId||null,events,exposures:exposures.filter(x=>visible.has(x.eventId)),exposureRules:record?[]:data.exposureRules||[],sources:record?HI_CORE.relevantSources(data,record,events,exposures):data.sources||[],manifest:data.manifest||{},classification:'event_evidence_not_causal_price_effects'});
  }
  if(path==='/map/api/record-history'){
   if(!record)return hiJSON(request,{version:data.version,asOf:data.asOf,records:data.records.map(({id,type,name,emirate,communityId,researchStatus})=>({id,type,name,emirate,communityId:communityId||null,researchStatus})),manifest:data.manifest||{}});
   const text=u.searchParams.get('assumptions');if(text&&text.length>8000)throw new TypeError('Full annual schedules exceed the compact GET limit; use the local scenario calculator.');
   let userAssumptions=null;if(text){try{userAssumptions=JSON.parse(text);}catch{throw new TypeError('Scenario assumptions must be valid JSON.');}HI_CORE.validateScenarioAssumptions(userAssumptions);}
   const hydrated=await hiHydrateRecord(record,data,env);
   return hiJSON(request,HI_CORE.recordHistory(data,hydrated,{userAssumptions}));
  }
  const eventId=u.searchParams.get('eventId'),event=(data.events||[]).find(e=>e.id===eventId);
  if(!record||!eventId)return hiJSON(request,{version:data.version,error:'Provide exact recordId and eventId.'},400);
  if(!event)return hiJSON(request,{version:data.version,error:'Unknown event.'},404);
  const metric=u.searchParams.get('metric')||'price',frequency=u.searchParams.get('frequency')||'monthly',scope=u.searchParams.get('scope')||'subject',seriesId=u.searchParams.get('seriesId')||null,hydrated=await hiHydrateRecord(record,data,env);
  const exposures=HI_CORE.recordExposures(data,record);
  return hiJSON(request,{version:data.version,asOf:data.asOf,recordId:record.id,event,study:HI_CORE.eventStudy(hydrated,event,{metric,frequency,scope,seriesId,asOf:data.asOf,sources:data.sources||[],exposures}),sources:HI_CORE.relevantSources(data,record,[event],exposures),manifest:data.manifest||{}});
 }catch(error){return hiJSON(request,{version:data.version,error:String(error.message||error)},error instanceof TypeError||error instanceof RangeError?400:503);}
};
